{
  "findings": [
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent reports that strangers can email their child through Google Classroom.",
      "stance": "risk",
      "quote": "Your kid will receive an email when the teacher posts an announcement. These emails come through your kid's email account, not in Classroom."
    },
    {
      "ref": "[D521]",
      "area": "money",
      "claim": "A parent reports that Google Classroom may push in-app purchases or loot boxes.",
      "stance": "neutral",
      "quote": "Google Classroom is just one part of Google's Workspace for Education, and some of the apps, including third-party programs, can be tracked."
    },
    {
      "ref": "[D521]",
      "area": "data",
      "claim": "A parent reports that Google may collect data on third‑party apps like YouTube and Maps if the administrator enables them.",
      "stance": "risk",
      "quote": "if the school's administrator enables Additional Services, such as YouTube and Maps, Google may collect data on those apps as it would for any of its other consumer apps."
    },
    {
      "ref": "[D521]",
      "area": "data",
      "claim": "A parent reports that third‑party developers could profile and target the child using collected data.",
      "stance": "risk",
      "quote": "those third parties could collect information from your kid, then profile and target them using that data."
    },
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, but they are unsure how it is enforced.",
      "stance": "neutral",
      "quote": "Logging in with a school account, rather than a personal Gmail account, protects kids from some data collection because education accounts can't be tracked or mined for data (beyond what's necessary for educational purposes)."
    },
    {
      "ref": "[D521]",
      "area": "content",
      "claim": "A parent reports that YouTube may be enabled in Classroom and could show mature content unless restricted mode is set.",
      "stance": "risk",
      "quote": "If your kid has YouTube enabled in their Classroom account, you'll need to speak to the admin, not the teacher, if you don't want your kid watching YouTube (the admin can also enable \"restricted mode\" for YouTube, which limits some mature content)."
    },
    {
      "ref": "[D521]",
      "area": "developer_record",
      "claim": "A parent reports that Google has not been fined or sued for data misuse related to Classroom.",
      "stance": "neutral",
      "quote": "Google doesn't share or sell student data to partners, and it vets the developers it uses for Classroom."
    }
  ]
}
